export function captureMarkup(t,handPath){return `<section class="capture-page"><video id="camera" autoplay playsinline muted></video><button class="scan-back" id="back" aria-label="${t('back')}">‹</button><div class="capture-reference"><svg viewBox="0 0 100 120" aria-hidden="true"><rect x="27" y="5" width="45" height="29" rx="2" fill="#e2e8ed" stroke="#71808c"/><path d="M32 13h13" stroke="#82909a"/><g transform="translate(4 38)"><path d="${handPath}" fill="#e5c1a8" stroke="#8e7567" stroke-width="2"/></g></svg></div><div class="capture-divider"><span>↑ ${t('card')}</span><span>↓ ${t('hand')}</span></div><div class="tilt-circle" id="tilt"><span class="tilt-target"></span><span class="tilt-bubble" id="tilt-bubble"></span></div><div class="tilt-value" id="angle">—°</div><div class="capture-checks">${t('checks').map((text,i)=>`<div class="capture-check" id="check-${i}"><span class="check-icon">⊗</span>${text}</div>`).join('')}</div><div class="capture-ready hidden" id="capture-ready"><span>✓</span><p>${t('hold')}</p></div><div class="capture-controls"><button class="upload-button" id="upload">${t('upload')}</button><button class="capture-shutter" id="shutter" aria-label="${t('shutter')}" disabled></button><span class="capture-info" id="capture-info">${t('modelLoading')}</span></div><input id="photo-file" type="file" accept="image/jpeg,image/png,image/webp" hidden><div class="capture-error hidden" id="camera-error"></div><div class="capture-countdown hidden" id="countdown"></div></section>`;}
export function drawCameraLevel(level){
const circle=document.querySelector('#tilt'),bubble=document.querySelector('#tilt-bubble'),angle=document.querySelector('#angle');if(!circle||!bubble||!angle)return;
if(level){angle.textContent=Math.round(level.angle)+'°';const magnitude=Math.hypot(level.x,level.y),radius=Math.min(30,level.angle*1.8);bubble.style.transform=`translate(${magnitude?level.x/magnitude*radius:0}px,${magnitude?level.y/magnitude*radius:0}px)`;circle.classList.toggle('good',level.angle<10);}else{angle.textContent='—°';circle.classList.remove('good');}
}
